{
  "status": "SUPPORTED",
  "task_summary": "Identify compatible components, fasten at workbench, leave tool on workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "assembly_target",
        "entity_kind": "OBJECT",
        "function": "The object on the desk that needs to be fastened.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["tray", "workpiece"],
        "required_properties": ["needs_fastening", "has_mounting_point"]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "The component required to secure the assembly.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "pin"],
        "required_properties": ["fits_assembly_target", "secure_connection"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastener.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "hammer"],
        "required_properties": ["applies_force", "engages_fastener"]
      },
      {
        "id": "storage_source",
        "entity_kind": "OBJECT",
        "function": "The container where the fastener is located.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["cabinet", "drawer"],
        "required_properties": ["contains_components", "openable"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The destination for the reusable equipment.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["desk", "table"],
        "required_properties": ["flat", "stable"]
      }
    ],
    "functional_relations": [
      {
        "id": "fastener_attached",
        "relation": "fastener is securely attached to assembly_target",
        "participant_roles": ["assembly_target", "fastener"]
      ,
      "required": true
      },
      {
        "id": "tool_resting",
        "relation": "fastening_tool is resting on workbench_surface",
        "participant_roles": ["fastening_tool", "workbench_surface"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_and_retrieve",
        "operation": "Open storage_source to find and retrieve fastener",
        "participant_roles": ["storage_source", "fastener"]
      ,
      "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "Use fastening_tool to attach fastener to assembly_target",
        "participant_roles": ["assembly_target", "fastener", "fastening_tool"]
      ,
      "operation_count": 1
      },
      {
        "id": "deposit_tool",
        "operation": "Place fastening_tool onto workbench_surface",
        "participant_roles": ["fastening_tool", "workbench_surface"]
      ,
      "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "assembly_target": [
        {
          "label": "black tray with yellow/grey blocks on desk"
        ,
        "visual_description": "A flat black object with yellow and grey components on top."
        }
      ],
      "storage_source": [
        {
          "label": "blue cabinet on desk"
        ,
          "visual_description": "A tall blue cabinet with a closed door."
        },
        {
          "label": "left blue drawer under desk"
        ,
          "visual_description": "A blue drawer with a white handle."
        },
        {
          "label": "right blue drawer under desk"
        ,
          "visual_description": "A blue drawer with a white handle."
        }
      ],
      "workbench_surface": [
        {
          "label": "wooden top of desk"
        ,
          "visual_description": "A light brown wooden surface."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue cabinet on desk",
        "visual_description": "Tall blue cabinet with a closed door.",
        "reason": "Closed storage structure, likely contains tools or components."
      },
      {
        "id": "left_drawer",
        "label": "left blue drawer under desk",
        "visual_description": "Blue drawer with a white handle.",
        "reason": "Closed storage structure, likely contains tools or components."
      },
      {
        "id": "right_drawer",
        "label": "right blue drawer under desk",
        "visual_description": "Blue drawer with a white handle.",
        "reason": "Closed storage structure, likely contains tools or components."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
